-- Validation assertions: abort transaction if expected counts are not met
do $$
declare
  v_players integer;
  v_matches integer;
  v_entries integer;
  v_perfs integer;
begin
  select count(*) into v_players from public.players;
  select count(*) into v_matches from public.matches where season = 2026;
  select count(*) into v_entries
    from public.match_team_entries e
    join public.matches m on m.match_id = e.match_id
    where m.season = 2026;
  select count(*) into v_perfs
    from public.player_match_performances p
    join public.match_team_entries e on e.source_match_id = p.source_match_id
    join public.matches m on m.match_id = e.match_id
    where m.season = 2026;

  if v_players <> 67 then
    raise exception 'Validation failed: expected 67 players, got %', v_players;
  end if;

  if v_matches <> 77 then
    raise exception 'Validation failed: expected 77 physical matches, got %', v_matches;
  end if;

  if v_entries <> 78 then
    raise exception 'Validation failed: expected 78 match team entries, got %', v_entries;
  end if;

  if v_perfs <> 824 then
    raise exception 'Validation failed: expected 824 performances, got %', v_perfs;
  end if;
end $$;

commit;

-- Final verification query
select
  (select count(*) from public.players) as players,
  (select count(*) from public.matches where season = 2026) as physical_matches,
  (
    select count(*)
    from public.match_team_entries e
    join public.matches m on m.match_id = e.match_id
    where m.season = 2026
  ) as match_team_entries,
  (
    select count(*)
    from public.player_match_performances p
    join public.match_team_entries e on e.source_match_id = p.source_match_id
    join public.matches m on m.match_id = e.match_id
    where m.season = 2026
  ) as player_match_performances;